function real(value, decimals = 4) {
    if (value === null) return '-';
    if (Math.abs(value) >= 1e21) return BigInt(value).toString() + '.' + '0'.repeat(decimals);
    const text = value.toFixed(decimals);
    return Number(text) === 0 ? (0).toFixed(decimals) : text;
}
